func _run_tests() -> void:
	var story_path := "res://story/main_story.json"
	if not check("file_main_story", FileAccess.file_exists(story_path), "Il file principale della storia res://story/main_story.json deve esistere"):
		return

	var validator_script := load("res://story/story_validator.gd")
	if not check("validator_presente", validator_script != null, "Lo script res://story/story_validator.gd deve essere presente e valido"):
		return

	var validator = validator_script.new()
	var val_errors: Array = []
	if validator.has_method("validate_chapter"):
		val_errors = validator.validate_chapter(story_path)

	check("validatore_senza_errori", val_errors.is_empty(), "StoryValidator non deve trovare errori nella storia (trovati: %s)" % str(val_errors))

	var files_cache: Dictionary = {}
