						labels_dict[lname] = i
			all_labels_by_file[fpath] = labels_dict
			visited_labels_by_file[fpath] = {}

		var cdata: Dictionary = files_cache[fpath]
		var clines: Array = cdata.get("lines", [])

		if idx >= clines.size():
			reached_endings[state_key] = true
